package com.digitalbase.ticketing.service;import com.digitalbase.ticketing.dto.*;import com.digitalbase.ticketing.enums.ProductStatus; // ---> Enum ကို Import လုပ်ထားပါသည် <---import com.digitalbase.ticketing.exception.ResourceNotFoundException;import com.digitalbase.ticketing.model.ClientProduct;import com.digitalbase.ticketing.model.Product;import com.digitalbase.ticketing.model.Ticket;import com.digitalbase.ticketing.model.User;import com.digitalbase.ticketing.repository.ClientProductRepository;import com.digitalbase.ticketing.repository.ProductRepository;import com.digitalbase.ticketing.repository.TicketRepository;import com.digitalbase.ticketing.repository.UserRepository;import lombok.RequiredArgsConstructor;import org.springframework.stereotype.Service;import java.time.Instant;import java.util.List;import java.util.stream.Collectors;@Service@RequiredArgsConstructorpublic class ClientProductServiceImpl implements ClientProductService {    private final ClientProductRepository clientProductRepository;    private final TicketRepository ticketRepository;    private final UserRepository userRepository;    private final ProductRepository productRepository;    @Override    public ClientProductResponse assignProductToClient(ClientProductRequest request) {        User user = userRepository.findById(request.getUserId())                .orElseThrow(() -> new ResourceNotFoundException("User not found"));        Product product = productRepository.findById(request.getProductId())                .orElseThrow(() -> new ResourceNotFoundException("Product not found"));        // ဤ Customer သည် ဤ Product ကို ရရှိပြီးသား ဖြစ်နေပါက အသစ်ထပ်မပေးဘဲ Error ပြန်ပေးမည်        if (clientProductRepository.existsByUserIdAndProductId(user.getId(), product.getId())) {            throw new RuntimeException("This client already has the product: " + product.getName());        }        ClientProduct clientProduct = ClientProduct.builder()                .user(user)                .product(product)                .supportPlan(request.getSupportPlan())                .purchasedDate(Instant.now())                .planEndDate(request.getPlanEndDate())                .totalMinutes(request.getTotalMinutes())                .availableMinutes(request.getTotalMinutes())                .status(ProductStatus.ACTIVE) // 👈 ဤနေရာတွင် boolean အစား Enum ဖြင့် ပြင်ဆင်ထားသည်                .build();        ClientProduct savedClientProduct = clientProductRepository.save(clientProduct);        return mapToResponse(savedClientProduct);    }    @Override    public MyProductDashboardResponse getMyProducts(String email) {        User user = userRepository.findByEmail(email)                .orElseThrow(() -> new ResourceNotFoundException("User not found"));        // ၁။ Database မှ Client ၏ Product အားလုံးကို ဆွဲထုတ်ပါမည်        List<ClientProduct> clientProducts = clientProductRepository.findAllByUserId(user.getId());        // ၂။ Dashboard အတွက် လိုအပ်သော တွက်ချက်မှုများ ပြုလုပ်ပါမည်        int totalProducts = clientProducts.size();        // 👈 ACTIVE ဖြစ်နေတာရော၊ သက်တမ်းကုန်ခါနီး (EXPIRING_SOON) ဖြစ်နေတာပါ Active အနေဖြင့် ရေတွက်ပါမည်        int activeProducts = (int) clientProducts.stream()                .filter(cp -> cp.getStatus() == ProductStatus.ACTIVE || cp.getStatus() == ProductStatus.EXPIRING_SOON)                .count();        int totalSlaHours = clientProducts.stream()                .mapToInt(ClientProduct::getTotalMinutes)                .sum() / 60; // မိနစ်ကို နာရီပြောင်းခြင်း        // Available Minutes သည် အနှုတ်ပြနေပါက Extra သုံးထားသည်ဟု ယူဆပြီး ပေါင်းပါမည်        int extraUsageHours = clientProducts.stream()                .filter(cp -> cp.getAvailableMinutes() < 0)                .mapToInt(cp -> Math.abs(cp.getAvailableMinutes()))                .sum() / 60;        // ၃။ သင်၏ မူလ mapToResponse ကို အသုံးပြု၍ List ပြောင်းပါမည်        List<ClientProductResponse> productResponses = clientProducts.stream()                .map(this::mapToResponse)                .collect(Collectors.toList());        // ၄။ DTO အသစ်ဖြင့် အားလုံးကို ထုပ်ပိုးပြီး ပြန်ပေးပါမည်        return MyProductDashboardResponse.builder()                .totalProducts(totalProducts)                .totalSlaHours(totalSlaHours)                .activeProducts(activeProducts)                .extraUsageHours(extraUsageHours)                .products(productResponses)                .build();    }    @Override    public ClientProductDetailResponse getClientProductDetails(Long clientProductId, String email) {        User user = userRepository.findByEmail(email)                .orElseThrow(() -> new ResourceNotFoundException("User not found"));        ClientProduct cp = clientProductRepository.findByIdAndUserId(clientProductId, user.getId())                .orElseThrow(() -> new ResourceNotFoundException("Product not found or access denied"));        long daysRemaining = 0;        if (cp.getPlanEndDate() != null) {            daysRemaining = java.time.temporal.ChronoUnit.DAYS.between(Instant.now(), cp.getPlanEndDate());            if (daysRemaining < 0) daysRemaining = 0;        }        int totalMins = cp.getTotalMinutes() != null ? cp.getTotalMinutes() : 0;        int availMins = cp.getAvailableMinutes() != null ? cp.getAvailableMinutes() : 0;        int usedMinsTotal = availMins >= 0 ? totalMins - availMins : totalMins;        int remainMinsTotal = Math.max(availMins, 0);        int extraMinsTotal = availMins < 0 ? Math.abs(availMins) : 0;        ClientProductDetailResponse.SlaDetails slaDetails = ClientProductDetailResponse.SlaDetails.builder()                .totalSlaHours(totalMins / 60)                .remainingHours(remainMinsTotal / 60)                .remainingMinutes(remainMinsTotal % 60)                .usedHours(usedMinsTotal / 60)                .usedMinutes(usedMinsTotal % 60)                .extraHours(extraMinsTotal / 60)                .extraMinutes(extraMinsTotal % 60)                .daysRemaining(daysRemaining)                .planEndDate(cp.getPlanEndDate())                .build();        ClientProductDetailResponse.SystemMetadata metadata = ClientProductDetailResponse.SystemMetadata.builder()                .productType(cp.getProduct().getProductType())                .supportPlan(cp.getSupportPlan())                .purchasedDate(cp.getPurchasedDate())                .planEndDate(cp.getPlanEndDate())                .build();        return ClientProductDetailResponse.builder()                .productName(cp.getProduct().getName())                .productDescription(cp.getProduct().getDescription())                .slaDetails(slaDetails)                .metadata(metadata)                .build();    }    @Override    public List<ProductTicketDto> getProductRelatedTickets(Long clientProductId, String email) {        User user = userRepository.findByEmail(email)                .orElseThrow(() -> new ResourceNotFoundException("User not found"));        ClientProduct cp = clientProductRepository.findByIdAndUserId(clientProductId, user.getId())                .orElseThrow(() -> new ResourceNotFoundException("Product not found or access denied"));        List<Ticket> tickets = ticketRepository.findAllByClientProductId(cp.getId());        return tickets.stream().map(t ->                ProductTicketDto.builder()                        .ticketId("DB-TK" + t.getId())                        .status(t.getStatus().name())                        .issueType(t.getIssueType().name())                        .assignedTeam(t.getDeveloper() != null ? t.getDeveloper().getFullName() : "Pending")                        .priority(t.getPriority() != null ? t.getPriority().name() : "Normal")                        .timeUsedMinutes(t.getSpentMinutes() != null ? t.getSpentMinutes() : 0)                        .build()        ).collect(Collectors.toList());    }    private ClientProductResponse mapToResponse(ClientProduct cp) {        return ClientProductResponse.builder()                .id(cp.getId())                .productName(cp.getProduct().getName())                .productDescription(cp.getProduct().getDescription())                .productType(cp.getProduct().getProductType())                .imageUrl(cp.getProduct().getImageUrl())                .supportPlan(cp.getSupportPlan())                .purchasedDate(cp.getPurchasedDate())                .planEndDate(cp.getPlanEndDate())                .availableMinutes(cp.getAvailableMinutes())                .totalMinutes(cp.getTotalMinutes())                .status(cp.getStatus().name()) // 👈 ဤနေရာတွင် boolean အစား Enum ၏ စာသားကို ပြောင်းလဲပေးပို့ပါသည်                .build();    }}